using System.Globalization;
using System.Text.Json;
namespace LocalChat;
sealed record MediaFrame(string Path,double Seconds);
static class MediaFrames {
 public static string Demuxer(string path)=>System.IO.Path.GetExtension(path).ToLowerInvariant() switch {".mp4" or ".mov" or ".m4v"=>"mov",".mkv" or ".webm"=>"matroska,webm",".avi"=>"avi",_=>throw new Exception("Поддерживаются MP4, MOV, MKV, WebM и AVI.")};
 public static async Task<List<MediaFrame>> Extract(string ffmpeg,string input,string output,CancellationToken ct){
  if(!System.IO.Path.IsPathFullyQualified(ffmpeg)||!File.Exists(ffmpeg)||!System.IO.Path.IsPathFullyQualified(input)||!File.Exists(input))throw new Exception("Нужны локальный FFmpeg и выбранный видеофайл.");if(new FileInfo(input).Length>200L*1024*1024)throw new Exception("Видео больше 200 МБ.");string format=Demuxer(input);string probe=System.IO.Path.Combine(System.IO.Path.GetDirectoryName(ffmpeg)!,OperatingSystem.IsWindows()?"ffprobe.exe":"ffprobe");if(!File.Exists(probe))throw new Exception("Рядом с FFmpeg нужен ffprobe. Выбери полную установку FFmpeg.");
  var checkedDuration=await SafeProcess.Run(probe,new[]{"-v","error","-protocol_whitelist","file,pipe","-f",format,"-select_streams","v:0","-show_entries","format=duration:stream=avg_frame_rate","-of","json",input},20,ct);
  if(checkedDuration.Exit!=0)throw new Exception("Не удалось прочитать видео.");using var metadata=JsonDocument.Parse(checkedDuration.Output);if(!metadata.RootElement.TryGetProperty("format",out var info)||!info.TryGetProperty("duration",out var value)||!double.TryParse(value.GetString(),NumberStyles.Float,CultureInfo.InvariantCulture,out var duration)||!double.IsFinite(duration)||duration<=0||duration>7200)throw new Exception("Не удалось прочитать длительность либо видео длиннее 2 часов.");
  double frameStep=1;var streams=metadata.RootElement.GetProperty("streams");if(streams.GetArrayLength()==0)throw new Exception("В файле нет видеодорожки.");if(streams[0].TryGetProperty("avg_frame_rate",out var fps)){var parts=(fps.GetString()??"").Split('/');if(parts.Length==2&&double.TryParse(parts[0],NumberStyles.Float,CultureInfo.InvariantCulture,out var num)&&double.TryParse(parts[1],NumberStyles.Float,CultureInfo.InvariantCulture,out var den)&&num>0&&den>0)frameStep=Math.Clamp(den/num,.001,duration);}
  Directory.CreateDirectory(output);var result=new List<MediaFrame>();for(int i=0;i<4;i++){double seconds=Math.Max(0,Math.Min(duration*(i+.5)/4,duration-frameStep));string file=System.IO.Path.Combine(output,$"frame-{i}.png");var rendered=await SafeProcess.Run(ffmpeg,new[]{"-v","error","-nostdin","-n","-max_alloc","134217728","-protocol_whitelist","file,pipe","-ss",seconds.ToString("0.###",CultureInfo.InvariantCulture),"-f",format,"-i",input,"-frames:v","1","-vf","scale=1024:768:force_original_aspect_ratio=decrease","-threads","1",file},30,ct);if(rendered.Exit!=0||!File.Exists(file)||new FileInfo(file).Length>5*1024*1024)throw new Exception("Не удалось декодировать кадр: "+rendered.Error[..Math.Min(500,rendered.Error.Length)]);result.Add(new(file,seconds));}return result;
 }
}
